    struct net_device *fb_dev;
    int err;

    if (!sit_net)
        return -EINVAL;

    sit_net->fb_tunnel_dev = NULL;

    if (sit_net->fb_tunnel_dev)
        return 0;

    fb_dev = alloc_netdev(sizeof(struct ip_tunnel_net), "sit%d",
                           NET_NAME_UNKNOWN, sit_setup);
    if (!fb_dev)
        return -ENOMEM;

    ip_tunnel_init(net, fb_dev, 0);

    err = register_netdev(fb_dev);
