        return err;
    }

    sit_net->fb_tunnel_dev = fb_dev;

    return 0;
}

int sit_init_net(struct net *net)
{
    struct sit_net *sit;

    sit = net_generic(net, sit_net_id);
    if (!sit)
        return -ENOMEM;

    sit->tunnels = NULL;
    sit->fb_tunnel_dev = NULL;

    if (ipv4_is_multicast(sit->fb_tunnel_local) ||
        ipv4_is_multicast(sit->fb_tunnel_remote))
        return 0;

    sit->fb_tunnel_dev = alloc_netdev(0, "sit%d", NET_NAME_UNKNOWN, sit_setup);
    if (!sit->fb_tunnel_dev)
        return -ENOMEM;

    sit->fb_tunnel_dev->rtnl_link_ops = &sit_link_ops;
    sit->fb_tunnel_dev->type = ARPHRD_SIT;
    sit->fb_tunnel_dev->mtu = 1500;
    sit->fb_tunnel_dev->hard_header_len = 0;
    sit->fb_tunnel_dev->flags = IFF_NOARP;
    sit->fb_tunnel_dev->priv_flags = IFF_TUNNEL | IFF_DYNADDR;

    if (register_netdevice(sit->fb_tunnel_dev) < 0) {
        free_netdev(sit->fb_tunnel_dev);
        return -EIO;
    }

    return 0;
}

int init_sit_network(struct net *net) {
    struct sit_net *sit = net_generic(net, sit_net_id);

    sit->tunnels = NULL;
    sit->tunnels_rdev = NULL;

    if (sit->fb_tunnel_dev)
        return 0;

    sit->fb_tunnel_dev = alloc_netdev(0, "sit%d", NET_NAME_UNKNOWN, sit_setup);
    if (!sit->fb_tunnel_dev)
        return -ENOMEM;

    sit->fb_tunnel_dev->rtnl_link_ops = &sit_link_ops;
    sit->fb_tunnel_dev->type = ARPHRD_SIT;
    sit->fb_tunnel_dev->flags = IFF_NOARP;
    sit->fb_tunnel_dev->priv_flags = IFF_ISATAP;

    if (register_netdevice(sit->fb_tunnel_dev) < 0) {
        free_netdev(sit->fb_tunnel_dev);
        return -EINVAL;
    }

    return 0;
}

int sit_net_init(struct net *net)
{
    struct sit_net *sit = net_generic(net, sit_net_id);
    struct net_device *dev;
    int err;

    if (sit->fb_tunnel_dev)
        return 0;

    dev = alloc_netdev(sizeof(struct ip_tunnel), "sit%d",
                       NET_NAME_UNKNOWN, sit_setup);
    if (!dev)
        return -ENOMEM;

    dev->rtnl_link_ops = &sit_link_ops;
    dev_net_set(dev, net);
    dev->features = NETIF_F_HW_CSUM | NETIF_F_NO_RX_HANDLER;

    err = register_netdevice(dev);
    if (err < 0)
        goto out_free;

    sit->fb_tunnel_dev = dev;
    return 0;

out_free:
    free_netdev(dev);
    return err;
}
